import{_ as t,o as e,c as a,a as r}from"./app.83c7065c.js";const m=JSON.parse('{"title":"国际化和本地化初步","description":"","frontmatter":{"title":"国际化和本地化初步","date":"2020-04-27"},"headers":[],"relativePath":"2020/i18n-l10n-intro.md","lastUpdated":1786184870000}'),d={name:"2020/i18n-l10n-intro.md"},o=r('<h3 id="写在前面" tabindex="-1">写在前面 <a class="header-anchor" href="#写在前面" aria-hidden="true">#</a></h3><p>公司项目网站改版在即，需要扩充国际化和本地化支持。</p><p>查资料看了下这两个东西，理清了一些概念，简单记录一下。</p><h3 id="国际化和本地化" tabindex="-1">国际化和本地化 <a class="header-anchor" href="#国际化和本地化" aria-hidden="true">#</a></h3><p>根据wiki的说法，<strong>国际化与本地化</strong>（internationalization and localization）是指修改软件使之能适应目标市场的语言、区差异以及技术需要。</p><p>因为这两个单词太长了，所以前者简写为i18n（表示i和n之间有18个字母），后者是L10n。分别用小写i和大写L是为了和之后的数字1区分，i18n和I18n，显然前者更容易辨识；L10n同理。</p><ul><li><p>国际化</p><p>将软件与特定语言及地区脱钩的过程，即软件移植到不同语言和地区时，不需要做工程上的改动</p></li><li><p>本地化</p><p>与国际化相反，指移植软件时，增加与特定区域有关的信息和必要翻译的过程</p></li></ul><p>举个例子，前端最常见的国际化场景是给文案增加不同的语言版本，比如一个按钮文案是“提交”，在英文状态下可能会改成&quot;Submit&quot;。</p><p>另一个例子是处理时间，用统一逻辑处理不同时区之间的时间，这个算国际化；但是不同地区时间显示的格式不一样，同样是英语国家，英国的时间一般是<code>dd/mm/yyyy</code>，而美国的就是<code>MM dd, yyyy</code>，这个算本地化。</p><p>更常见的本地化场景是货币，不同国家的货币一般来说都是不同的，符号不同、计数的方式也不同。比如欧元区的德国，除了欧元的货币符号与美元不同之外，逗号和小数点的规则完全相反，<code>2.100,50</code>数值于美国的<code>2,100.50</code>。</p><table><thead><tr><th>地区</th><th>货币</th><th>日期</th></tr></thead><tbody><tr><td>美国</td><td>$1,234.56</td><td>Apr 27, 2020</td></tr><tr><td>英国</td><td>£1,234.56</td><td>27/04/2020</td></tr><tr><td>德国</td><td>1.234,56 €</td><td>27/04/2020</td></tr><tr><td>中国</td><td>¥1234.56</td><td>2020/04/27</td></tr></tbody></table><h3 id="地区设置locale" tabindex="-1">地区设置Locale <a class="header-anchor" href="#地区设置locale" aria-hidden="true">#</a></h3><p>有了国际化和本地化的支持，那么下一步就是要获取用户的位置了，否则无法有效根据不同用户背景提供更匹配的服务，于是引入了一个地区设置locale的概念。</p><p>从用户的角度来说，操作系统一般会有一组相应的环境变量设置locale，而对于网站/服务提供者来说，其实locale更像是一种推定，根据已获得的某些用户数据，推测用户的背景，并让网站/服务根据这个假设为用户提供（可能）更匹配的服务，比如语言。后面讲到语言类别的时候会更具体的讲到。</p><h3 id="例子-语言设置" tabindex="-1">例子： 语言设置 <a class="header-anchor" href="#例子-语言设置" aria-hidden="true">#</a></h3><h4 id="如何获取用户语言设置" tabindex="-1">如何获取用户语言设置 <a class="header-anchor" href="#如何获取用户语言设置" aria-hidden="true">#</a></h4><p>优先级：<a href="https://support.google.com/webmasters/answer/182192?hl=en&amp;ref_topic=2370587" target="_blank" rel="noreferrer">https://support.google.com/webmasters/answer/182192?hl=en&amp;ref_topic=2370587</a></p><p>domain-&gt;sub-domain-&gt;subdirectories-&gt;query parameters-&gt;http header accept-language-&gt;cookie-&gt;user agent</p><h4 id="google如何检索不同语言版本" tabindex="-1">google如何检索不同语言版本 <a class="header-anchor" href="#google如何检索不同语言版本" aria-hidden="true">#</a></h4><p><a href="https://support.google.com/webmasters/answer/182192?hl=en&amp;ref_topic=2370587" target="_blank" rel="noreferrer">https://support.google.com/webmasters/answer/182192?hl=en&amp;ref_topic=2370587</a></p>',20),n=[o];function i(p,h,s,c,l,_){return e(),a("div",null,n)}const u=t(d,[["render",i]]);export{m as __pageData,u as default};
